SELECT p.gender, a.admission_type, s.discharge_location, s.deathtime - s.admittime AS length_of_stay, percent_rank() OVER (ORDER BY s.deathtime - s.admittime) AS percentile_rank FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN icustays s ON a.hadm_id = s.subject_id WHERE p.gender = 'F' AND p.anchor_age = 42 AND p.anchor_year_group BETWEEN 37 AND 47 AND a.admission_type IN ('urgent', 'emergency') AND s.discharge_location IN ('home', 'facility', 'in-hospital death') AND s.deathtime - s.admittime <= 7 GROUP BY p.gender, a.admission_type, s.discharge_location, length_of_stay ORDER BY length_of_stay NULLS LAST;